#include <memory>

// This concept is difficult to demonstrate cleanly without the full C++98
// implementation showing the conversion operators involving auto_ptr_ref.
// The key usage pattern relies on implicit conversion from temporary auto_ptr:

std::auto_ptr<int> create_resource() {
    return std::auto_ptr<int>(new int(5));
}

int main() {
    // Ownership transfer from a temporary (rvalue).
    // This relies internally on auto_ptr_ref conversions in C++98/03.
    std::auto_ptr<int> p = create_resource();

    // In C++11, this transfer is handled by move semantics/RVO.
    // In C++03, auto_ptr_ref facilitates this behavior by ensuring
    // the assignment operator can correctly consume the temporary.

    if (p.get() != nullptr) {
        // Resource is successfully owned by p
    }
}
